    fn prepare_return_pending_handoff_for_test(
        fixture: &RepositoryFixture,
        tag: &str,
    ) -> (BoundSessionSeed, BoundSessionSeed, HandoffId, String) {
        let (source, recipient) = seed_handoff_parties(fixture, tag);
        let created = create_handoff_for_test(fixture, tag, &source, &recipient);
        let handoff_id = created.handoff.handoff_id.clone();
        let correlation = format!("{tag}:correlation");
        fixture
            .repository
            .accept_handoff(&AcceptHandoffCommand {
                handoff_id: handoff_id.clone(),
                source: handoff_authority(&source),
                recipient: handoff_authority(&recipient),
                expected_handoff_revision: 1,
                metadata: handoff_metadata(
                    &format!("{tag}:accept"),
                    &correlation,
                    "2026-08-09T00:01:00Z",
                ),
                test_clock_now: handoff_server_now("2026-08-09T00:01:00Z"),
            })
            .expect("accept handoff for returned-lineage fixture");
        fixture
            .repository
            .request_handoff_return(&RequestHandoffReturnCommand {
                handoff_id: handoff_id.clone(),
                source: handoff_authority(&source),
                expected_handoff_revision: 2,
                return_by: "2026-08-09T00:10:00Z".to_string(),
                metadata: handoff_metadata(
                    &format!("{tag}:request-return"),
                    &correlation,
                    "2026-08-09T00:02:00Z",
                ),
                test_clock_now: handoff_server_now("2026-08-09T00:02:00Z"),
            })
            .expect("request return for returned-lineage fixture");
        (source, recipient, handoff_id, correlation)
    }

    fn create_returned_handoff_for_test(
        fixture: &RepositoryFixture,
        tag: &str,
    ) -> (
        BoundSessionSeed,
        BoundSessionSeed,
        M3HandoffCommandOutcome,
        OpaqueRef,
    ) {
        let (source, recipient, handoff_id, correlation) =
            prepare_return_pending_handoff_for_test(fixture, tag);
        let validation_receipt_ref =
            fresh_source_application_base_receipt(fixture, &format!("{tag}:validation"), &source);
        let returned = fixture
            .repository
            .record_handoff_return_result(&RecordHandoffReturnResultCommand {
                handoff_id,
                source: handoff_authority(&source),
                recipient: handoff_authority(&recipient),
                expected_handoff_revision: 3,
                result: HandoffReturnResult::Returned {
                    result_ref: opaque(format!("{tag}:returned-result")),
                    result_hash: Sha256Digest::of_bytes(
                        format!("{tag}:returned-result").as_bytes(),
                    ),
                    source_object_validation: HandoffSourceObjectValidationProof {
                        role_session_id: source.role_session_id.clone(),
                        binding: source.binding.clone(),
                        object_ref: source.binding.current_object_ref.clone(),
                        validation_receipt_ref: validation_receipt_ref.clone(),
                    },
                },
                metadata: handoff_metadata(
                    &format!("{tag}:returned"),
                    &correlation,
                    "2026-08-09T00:03:00Z",
                ),
                test_clock_now: handoff_server_now("2026-08-09T00:03:00Z"),
            })
            .expect("persist returned handoff with source validation lineage");
        (source, recipient, returned, validation_receipt_ref)
    }

    fn create_handoff_with_narrowed_source_binding_for_test(
        fixture: &RepositoryFixture,
        tag: &str,
    ) -> (BoundSessionSeed, M3HandoffCommandOutcome) {
        let (source, recipient) = seed_handoff_parties(fixture, tag);
        let narrowed_snapshot = format!("permission:{tag}:source:v2");
        let narrowed_binding = server_binding(&format!("{tag}:source"), &narrowed_snapshot);
        let narrowed_permission = permission(
            &narrowed_snapshot,
            &["capability:read"],
            &["capability:write"],
            &["constraint:read-only"],
        );
        mint_detached_handoff_permission_descriptor_for_test(
            fixture,
            &format!("{tag}:source:v2"),
            &narrowed_permission,
        );
        let mut command = create_handoff_command_for_test(fixture, tag, &source, &recipient);
        command.source = handoff_authority_with(
            &source,
            narrowed_binding.clone(),
            source.permission.clone(),
            narrowed_permission,
            1,
        );
        command.permission_request.source_permission_snapshot_ref =
            narrowed_binding.permission_snapshot_ref;
        let created = fixture
            .repository
            .create_handoff(&command)
            .expect("create handoff after a bounded source permission narrowing");
        assert_eq!(created.command_receipt.actor_binding_revision, 2);
        (source, created)
    }

    fn seed_starting_turn(
        fixture: &RepositoryFixture,
        tag: &str,
        claim_effect: bool,
    ) -> StartingTurnSeed {
        let bound = seed_bound_session(
            fixture,
            tag,
            &format!("namespace:{tag}"),
            &format!("conversation:{tag}"),
        );
        let context_reference = context_ref(format!("context:{tag}"));
        fixture
            .repository
            .upsert_conversation_context(&UpsertConversationContextCommand {
                context: context_for(tag, &bound, context_reference.clone()),
                binding: bound.binding.clone(),
                previous_permission: Some(bound.permission.clone()),
                current_permission: Some(bound.permission.clone()),
                expected_session_revision: 1,
                metadata: metadata(&format!("{tag}:context")),
            })
            .expect("seed conversation context");
        let role_turn_id = turn_id(format!("turn:{tag}"));
        let started = fixture
            .repository
            .start_role_turn(&StartRoleTurnCommand {
                turn_id: role_turn_id.clone(),
                role_session_id: bound.role_session_id.clone(),
                binding: bound.binding.clone(),
                input_ref: opaque(format!("input:{tag}")),
                immutable: TurnImmutableRequest {
                    input_hash: Sha256Digest::of_bytes(format!("input:{tag}").as_bytes()),
                    expected_session_revision: 1,
                    conversation_context_ref: context_reference,
                    provider_handle_ref: bound.provider_handle.handle_ref.clone(),
                },
                previous_permission: Some(bound.permission.clone()),
                current_permission: Some(bound.permission.clone()),
                metadata: metadata(&format!("{tag}:start")),
            })
            .expect("seed registered turn effect");
        let effect = started.provider_effect.expect("seed turn effect");
        let provider_attempt_ref = claim_effect.then(|| opaque(format!("attempt:{tag}:start")));
        if let Some(provider_attempt_ref) = &provider_attempt_ref {
            let claimed = fixture
                .repository
                .claim_registered_provider_effect(&ClaimProviderEffectCommand {
                    effect_attempt_id: effect.effect_attempt_id.clone(),
                    provider_attempt_ref: provider_attempt_ref.clone(),
                    binding: bound.binding.clone(),
                    expected_session_revision: 1,
                    metadata: effect_metadata_with_correlation(
                        &format!("{tag}:start-claim"),
                        &format!("{tag}:start"),
                    ),
                })
                .expect("seed claimed turn effect");
            assert!(claimed.dispatch_granted);
        }
        StartingTurnSeed {
            bound,
            turn_id: role_turn_id,
            effect,
            provider_attempt_ref,
        }
    }

    fn binding(permission_snapshot_ref: &str) -> ServerResolvedBinding {
        ServerResolvedBinding::from_server_canonical(
            "actor:a",
            "role:worker",
            "scope:project-a",
            "object:work-item-a",
            "channel:agent",
            permission_snapshot_ref,
        )
        .expect("valid server-resolved binding")
    }

    fn request_key() -> RequestIdempotencyKey {
        RequestIdempotencyKey::try_from_canonical("request:1")
            .expect("valid request idempotency key")
    }

    #[test]
    fn owner_fingerprint_is_stable_and_excludes_permission_snapshot() {
        let first = owner_fingerprint(
            "actor:a",
            "role:worker",
            "scope:project-a",
            "object:work-item-a",
            "channel:agent",
        )
        .expect("fingerprint");
        let second = owner_fingerprint(
            "actor:a",
            "role:worker",
            "scope:project-a",
            "object:work-item-a",
            "channel:agent",
        )
        .expect("same fingerprint");
        assert_eq!(first, second);
        assert_eq!(first.as_str().len(), 64);
    }

    #[test]
    fn create_key_and_immutable_request_fingerprint_are_separate() {
        let original = role_session_create_idempotency_identity(
            &binding("permission:snapshot-1"),
            request_key(),
        )
        .expect("identity");
        let divergent = role_session_create_idempotency_identity(
            &binding("permission:snapshot-2"),
            request_key(),
        )
        .expect("identity");
        assert_eq!(
            original.base_idempotency_key,
            divergent.base_idempotency_key
        );
        assert_ne!(original.request_fingerprint, divergent.request_fingerprint);
        assert!(matches!(
            classify_idempotency_replay(
                &original.idempotency_scope_ref,
                original.base_idempotency_key.as_str(),
                &original.request_fingerprint,
                &divergent,
                ()
            )
            .expect("classification"),
            M3IdempotencyLookup::DivergentReuse
        ));
    }

    #[test]
    fn turn_fingerprint_includes_cas_revision() {
        let original = TurnImmutableRequest {
            input_hash: Sha256Digest::of_bytes(b"input"),
            expected_session_revision: 4,
            conversation_context_ref: ConversationContextRef::try_from_canonical("context:1")
                .expect("context ref"),
            provider_handle_ref: ProviderHandleRef::try_from_canonical("handle:1")
                .expect("handle ref"),
        };
        let mut stale = original.clone();
        stale.expected_session_revision = 3;
        let role_session_id =
            RoleSessionId::try_from_canonical("session:1").expect("role session id");
        let first = role_turn_idempotency_identity(&role_session_id, request_key(), &original)
            .expect("identity");
        let second = role_turn_idempotency_identity(&role_session_id, request_key(), &stale)
            .expect("identity");
        assert_eq!(first.base_idempotency_key, second.base_idempotency_key);
        assert_ne!(first.request_fingerprint, second.request_fingerprint);
    }

